import pytest
import jsonschema

@pytest.mark.parametrize("username, password, expected_status_code, expected_description", [
    ("validUser", "validPassword", 200, "successful operation"),
    ("invalidUser", "invalidPassword", 400, "Invalid username/password supplied"),
    (None, None, 400, "Invalid username/password supplied"),
    ("validUser", None, 400, "Invalid username/password supplied"),
    (None, "validPassword", 400, "Invalid username/password supplied")
])
def test_login_user(
        api_client,
        username,
        password,
        expected_status_code,
        expected_description
):
    """
    Test the /user/login endpoint with different username and password combinations.

    Args:
        api_client: The API client instance from conftest.py
        username (str): Username for login
        password (str): Password for login
        expected_status_code (int): Expected HTTP status code
        expected_description (str): Expected response description
    """

    params = {}
    if username is not None:
        params["username"] = username
    if password is not None:
        params["password"] = password

    response = api_client.get("/user/login", params=params)
    
    assert response.status_code == expected_status_code
    if expected_status_code == 200:
        assert "X-Rate-Limit" in response.headers
        assert "X-Expires-After" in response.headers
        if response.headers["Content-Type"] == "application/json":
            assert isinstance(response.json(), str)
        elif response.headers["Content-Type"] == "application/xml":
            assert isinstance(response.text, str)
        else:
            pytest.fail(f"Unexpected content type: {response.headers['Content-Type']}")
    elif expected_status_code == 400:
        assert response.json().get("description", "") == expected_description
    else:
        pytest.fail(f"Unhandled status code: {response.status_code}")


def test_login_user_missing_authentication(api_client):
    """
    Test /user/login endpoint without authentication headers.

    Args:
        api_client: The API client instance from conftest.py
    """
    response = api_client.get("/user/login", params={"username": "user", "password": "pass"})
    assert response.status_code == 400, \
        "Expected 400 Bad Request if credentials are missing."


@pytest.mark.parametrize("headers", [
    {"Authorization": "Bearer INVALID_TOKEN"},
    {}
])
def test_login_user_invalid_authentication(api_client, headers):
    """
    Test /user/login with invalid headers or missing headers.

    Args:
        api_client: The API client instance from conftest.py
        headers (dict): Authorization headers
    """
    response = api_client.get("/user/login", params={"username": "user", "password": "pass"}, headers=headers)
    assert response.status_code == 400, \
        f"Expected 400 Bad Request with headers: {headers}"


